const DESKTOP_HOVER = '(min-width: 761px) and (hover: hover) and (pointer: fine)';
const TOUCH_POINTER = '(any-pointer: coarse)';

export function supportsDesktopHover() {
  return typeof window !== 'undefined'
    && typeof window.matchMedia === 'function'
    && window.matchMedia(DESKTOP_HOVER).matches
    && !window.matchMedia(TOUCH_POINTER).matches;
}

export function watchDesktopHover(update) {
  const queries = [window.matchMedia(DESKTOP_HOVER), window.matchMedia(TOUCH_POINTER)];
  const sync = () => update(supportsDesktopHover());
  queries.forEach(query => query.addEventListener('change', sync));
  sync();
  return () => queries.forEach(query => query.removeEventListener('change', sync));
}
